"""Draft-vocabulary records pin both generated bytes and generation inputs."""

import importlib.util
import json
import sys
import tempfile
import unittest
from pathlib import Path
from types import ModuleType
from unittest.mock import MagicMock, patch

from dev.tools.draft_vocabulary_manifest import (
    capture_inputs,
    digest,
    manifest_path,
    validate_manifest,
    write_manifest,
)


class DraftVocabularyManifestTest(unittest.TestCase):
    def test_records_exact_inputs_and_invocation(self):
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            corpus = root / "corpus"
            corpus.mkdir()
            tokenizer = root / "tokenizer.json"
            source = root / "source.cpp"
            bitmap = root / "bitmap.cpp"
            manifest = manifest_path(bitmap)
            for path in (tokenizer, source, bitmap, corpus / "sample.parquet"):
                path.write_bytes(path.name.encode())
            command = ["python", "generator.py", "--code", "path with spaces"]
            with patch(
                "dev.tools.draft_vocabulary_manifest.importlib.metadata.version",
                return_value="pinned",
            ):
                write_manifest(manifest, tokenizer, corpus, [source], bitmap, command)
                first = validate_manifest(bitmap)
                self.assertEqual(first["generated_cpp_sha256"], digest(bitmap))
                self.assertEqual(
                    first["inputs"]["tokenizer"]["sha256"], digest(tokenizer)
                )
                self.assertIn("'path with spaces'", first["exact_invocation"])
                source.write_text("changed input")
                write_manifest(manifest, tokenizer, corpus, [source], bitmap, command)
            second = json.loads(manifest.read_text())
            self.assertNotEqual(
                first["input_identity_sha256"], second["input_identity_sha256"]
            )

    def test_output_can_also_be_an_input(self):
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            tokenizer = root / "tokenizer.json"
            bitmap = root / "bitmap.cpp"
            corpus = root / "corpus"
            corpus.mkdir()
            tokenizer.write_text("tokenizer")
            bitmap.write_text("old bitmap used while ranking")
            old_digest = digest(bitmap)
            inputs = capture_inputs(tokenizer, corpus, [bitmap])
            bitmap.write_text("generated bitmap")
            with patch(
                "dev.tools.draft_vocabulary_manifest.importlib.metadata.version",
                return_value="pinned",
            ):
                write_manifest(
                    root / "record.json",
                    tokenizer,
                    corpus,
                    [bitmap],
                    bitmap,
                    ["generator"],
                    inputs=inputs,
                )
            record = json.loads((root / "record.json").read_text())
            self.assertEqual(record["inputs"]["code"][0]["sha256"], old_digest)
            self.assertEqual(record["generated_cpp_sha256"], digest(bitmap))

    def test_generator_default_record_passes_checked_in_validator(self):
        # Stub expensive corpus ranking, but run the generator's main/output
        # manifest path and schema exactly as a real regeneration does.
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            corpus = root / "corpus"
            code = root / "code"
            corpus.mkdir()
            code.mkdir()
            tokenizer = root / "tokenizer.json"
            tokenizer.write_text("fixture tokenizer")
            cpp = root / "Vocabulary.cpp"
            numpy = MagicMock()
            numpy.sort.side_effect = lambda tokens: tokens
            arrow = ModuleType("pyarrow")
            arrow.parquet = MagicMock()
            dependencies = {
                "numpy": numpy,
                "pyarrow": arrow,
                "pyarrow.parquet": arrow.parquet,
                "tokenizers": MagicMock(),
            }
            spec = importlib.util.spec_from_file_location(
                "dev.tools.draft_vocabulary",
                Path(__file__).resolve().parents[2] / "tools/draft_vocabulary.py",
            )
            module = importlib.util.module_from_spec(spec)
            command = [
                "draft_vocabulary.py",
                "--tokenizer",
                str(tokenizer),
                "--corpus",
                str(corpus),
                "--code",
                str(code),
                "--cpp",
                str(cpp),
            ]
            with (
                patch.dict(sys.modules, dependencies),
                patch.object(sys, "argv", command),
            ):
                spec.loader.exec_module(module)
                with (
                    patch.object(module, "rank", return_value=[0, 1]),
                    patch.object(
                        module,
                        "write_cpp",
                        side_effect=lambda path, tokens: Path(path).write_text(
                            "generated bitmap"
                        ),
                    ),
                    patch(
                        "dev.tools.draft_vocabulary_manifest.importlib.metadata.version",
                        return_value="pinned",
                    ),
                ):
                    module.main()
            record = validate_manifest(cpp)
            self.assertIn("--tokenizer", record["exact_invocation"])
            self.assertTrue(cpp.with_suffix(".manifest.json").exists())
            self.assertFalse(Path(str(cpp) + ".manifest.json").exists())

    def test_checked_in_bitmap_matches_legacy_record(self):
        root = Path(__file__).resolve().parents[3]
        cpp = root / "runtime/model/Qwen4DraftVocabularyData.cpp"
        record = validate_manifest(cpp)
        self.assertEqual(record["generated_cpp_sha256"], digest(cpp))
        self.assertIsNone(record["exact_invocation"])
